{"file_path": "C:\Users\UserX\Downloads\实习\_extract.py", "content": "# -*- coding: utf-8 -*-
import sys, io, os
out = io.StringIO()

def w(s=""):
    out.write(str(s) + "\n")

# ---------- DOCX ----------
docx_path = r"C:\Users\UserX\Desktop\UserX_简历.docx"
w("=" * 70)
w("DOCX: " + docx_path)
w("=" * 70)
try:
    from docx import Document
    d = Document(docx_path)
    w("--- paragraphs ---")
    for p in d.paragraphs:
        t = p.text.strip()
        if t:
            w(t)
    w("--- tables: %d ---" % len(d.tables))
    for ti, tb in enumerate(d.tables):
        w("### TABLE %d  rows=%d cols=%d" % (ti, len(tb.rows), len(tb.columns)))
        for r in tb.rows:
            cells = [c.text.strip().replace("\n", " / ") for c in r.cells]
            w(" | ".join(cells))
    # headers/footers
    for si, sec in enumerate(d.sections):
        for name, part in (("header", sec.header), ("footer", sec.footer)):
            txt = " ".join(p.text.strip() for p in part.paragraphs if p.text.strip())
            if txt:
                w("[%s%d] %s" % (name, si, txt))
except Exception as e:
    w("DOCX ERROR: %r" % (e,))

# ---------- XLSX ----------
xlsx_path = r"C:\Users\UserX\xwechat_files\wxid_wd0ci9uaa5l322_9546\temp\RWTemp\2026-09\d502ce0559183504a8ccbedfd8344a5c\UserX综测(1).xlsx"
w("")
w("=" * 70)
w("XLSX: " + xlsx_path)
w("=" * 70)
try:
    import openpyxl
    wb = openpyxl.load_workbook(xlsx_path, data_only=True)
    for ws in wb.worksheets:
        w("")
        w("### SHEET: %s  dims=%s  max_row=%d max_col=%d" % (ws.title, ws.dimensions, ws.max_row, ws.max_column))
        for row in ws.iter_rows():
            vals = []
            for c in row:
                v = c.value
                if v is None:
                    vals.append("")
                else:
                    vals.append(str(v).strip().replace("\n", " "))
            line = " | ".join(vals).rstrip(" |")
            if line.strip():
                w(line)
except Exception as e:
    w("XLSX ERROR: %r" % (e,))

data = out.getvalue()
with open(r"C:\Users\UserX\Downloads\实习\_extract.txt", "w", encoding="utf-8") as f:
    f.write(data)
print("OK chars=%d" % len(data))
